const t = $("Sub").item.json;
const query = "query GetIssue($issueId: String!) { issue(id: $issueId) { id identifier title description url priority priorityLabel labels { nodes { id name } } state { id name type } team { id name key } assignee { id name email } creator { id name email } comments(first: 50) { nodes { id body createdAt user { id name } } } children { nodes { id identifier title state { id name type } } } parent { id identifier title description } attachments { nodes { id url title metadata } } } }";
return { json: { graphqlBody: JSON.stringify({ query, variables: { issueId: t.issueId } }) } };

const r = $json;
const BOT_USER_ID = "65049f30-62b1-4061-88a4-f02c572a91ca";
const DEFAULT_STATE = {"schemaVersion":1,"status":"IDLE","runId":null,"startedAt":null,"finishedAt":null,"attempts":0,"clarificationRounds":0,"phase":null,"workflowIds":[],"lastProcessedCommentId":null,"rollingSummary":"","pendingFeedback":[],"halted":false};
if (r.errors) {
  return { json: { ok: false, errors: r.errors.map(e => e.message).join("; ") } };
}
if (r.error) {
  return { json: { ok: false, errors: r.error.message || JSON.stringify(r.error) } };
}
const issue = r.data?.issue;
if (!issue) {
  return { json: { ok: false, errors: "Issue not found" } };
}
let comments = (issue.comments?.nodes || []).map(c => ({
  id: c.id,
  body: c.body || "",
  createdAt: c.createdAt,
  userId: c.user?.id || "",
  userName: c.user?.name || "",
  isBot: c.user?.id === BOT_USER_ID
}));
comments.sort((a, b) => (a.createdAt || "").localeCompare(b.createdAt || ""));
if (comments.length > 20) { comments = comments.slice(-20); }
const subIssues = (issue.children?.nodes || []).map(s => ({
  id: s.id,
  identifier: s.identifier,
  title: s.title,
  state: s.state ? { id: s.state.id, name: s.state.name, type: s.state.type } : null
}));
const attachments = issue.attachments?.nodes || [];
const darwinAtt = attachments.find(a => a.url === "darwin://build-state");
let buildState = { ...DEFAULT_STATE };
if (darwinAtt?.metadata) {
  const m = darwinAtt.metadata;
  if (typeof m === "object") { Object.assign(buildState, m); }
  else if (typeof m === "string") { try { Object.assign(buildState, JSON.parse(m)); } catch(e) {} }
}
return { json: {
  ok: true,
  issue: {
    id: issue.id,
    identifier: issue.identifier,
    title: issue.title,
    description: issue.description || "",
    url: issue.url || "",
    priority: issue.priority,
    priorityLabel: issue.priorityLabel || "",
    labels: (issue.labels?.nodes || []).map(l => ({ id: l.id, name: l.name })),
    state: issue.state ? { id: issue.state.id, name: issue.state.name, type: issue.state.type } : null,
    team: issue.team ? { id: issue.team.id, name: issue.team.name, key: issue.team.key } : null,
    assignee: issue.assignee ? { id: issue.assignee.id, name: issue.assignee.name, email: issue.assignee.email || "" } : null,
    creator: issue.creator ? { id: issue.creator.id, name: issue.creator.name, email: issue.creator.email || "" } : null
  },
  comments,
  subIssues,
  parent: issue.parent ? {
    id: issue.parent.id,
    identifier: issue.parent.identifier,
    title: issue.parent.title,
    description: issue.parent.description || ""
  } : null,
  buildState
} };
